438	/** The store of a sheet's settings and of the roles it gives user names, kept per sheet. */
439	@Repository
440	public class Settings {
441	
442	    public static final String CLERK_LIMIT = "clerk-limit";
443	    public static final String FLOOR = "floor";
444	    public static final String FLOOR_DEFAULT = "1.00";
445	    public static final String TERMS = "terms";
446	    public static final String TERMS_DEFAULT = "14";
447	    /** The grades a sheet may give terms of their own, each kept under {@link #gradeTermsKey}. */
448	    public static final List<String> GRADES = List.of("A", "B", "C");
449	    public static final String LATE_PCT = "late-pct";
450	    public static final String LATE_PCT_DEFAULT = "0.00";
451	    public static final String POLICY_DATE = "policy-date";
452	    public static final String PERIOD_NUMBERING_FROM = "period-numbering-from";
453	    /** The default date of a new claim in place of the sheet's today (undated); blank is off. */
454	    public static final String ENTRY_DATE = "entry-date";
455	    public static final String CAP = "cap";
456	    public static final String PROOF_THRESHOLD = "proof-threshold";
457	    public static final String NOTE_THRESHOLD = "note-threshold";
458	    /** Days after a period's to-date it stays open once the sheet's today passes it (undated); blank is off. */
459	    public static final String GRACE_DAYS = "grace-days";
460	    /** The settings that carry a figure: each value is kept from a from-date (see {@link #on}). */
461	    public static final List<String> DATED = List.of(CLERK_LIMIT, FLOOR, TERMS, gradeTermsKey("A"), gradeTermsKey("B"),
462	            gradeTermsKey("C"), LATE_PCT, CAP, PROOF_THRESHOLD, NOTE_THRESHOLD, gradeGraceKey("A"), gradeGraceKey("B"), gradeGraceKey("C"));
463	    public static final String CLERK = "clerk";
464	    public static final String STEWARD = "steward";
465	    /** A role that sees everything and may change nothing; never one the permission matrix allows an action to. */
466	    public static final String VIEWER = "viewer";
467	    /** The roles a sheet gives user names. */
468	    public static final List<String> ROLES = List.of(CLERK, STEWARD);
469	    /** The actions the permission matrix decides, each kept (undated) under {@link #permKey}. */
470	    public static final List<String> PERM_ACTIONS = List.of("open", "settle", "void", "reassign", "close", "reopen");
471	
472	    private final JdbcTemplate jdbc;
473	    private final Sheets sheets;
474	    private final Claims claims;
475	    private final Delegations delegations;
476	    private final People people;
477	
478	    public Settings(JdbcTemplate jdbc, Sheets sheets, Claims claims, Delegations delegations, People people) {
479	        this.jdbc = jdbc;
480	        this.sheets = sheets;
481	        this.claims = claims;
482	        this.delegations = delegations;
483	        this.people = people;
484	    }
485	
486	    /** The setting's value; "" when it was never set. */
487	    public String get(String sheetId, String key) {
488	        List<String> values = jdbc.queryForList("SELECT setting_value FROM " + AsOf.table("setting") + " WHERE sheet_id = ? AND setting_key = ?",
489	                String.class, sheetId, key);
490	        return values.isEmpty() ? "" : values.get(0);
491	    }
492	
493	    public void set(String sheetId, String key, String value) {
494	        jdbc.update("MERGE INTO setting (sheet_id, setting_key, setting_value) KEY (sheet_id, setting_key) VALUES (?, ?, ?)",
495	                sheetId, key, value);
496	    }
497	
498	    /** A dated setting's value from a from-date; one already recorded from that date is replaced. */
499	    public void set(String sheetId, String key, LocalDate from, String value) {
500	        jdbc.update("MERGE INTO setting_from (sheet_id, setting_key, from_date, setting_value) KEY (sheet_id, setting_key, from_date)"
501	                + " VALUES (?, ?, ?, ?)", sheetId, key, java.sql.Date.valueOf(from), value);
502	    }
503	
504	    /** A dated setting's value in force on the date: the one with the latest from-date on or before it; "" when there is none. */
505	    public String on(String sheetId, String key, LocalDate date) {
506	        List<String> values = jdbc.queryForList("SELECT setting_value FROM " + AsOf.table("setting_from") + " WHERE sheet_id = ? AND setting_key = ?"
507	                + " AND from_date <= ? ORDER BY from_date DESC LIMIT 1", String.class, sheetId, key, java.sql.Date.valueOf(date));
508	        return values.isEmpty() ? "" : values.get(0);
509	    }
510	
511	    /** A dated setting's values, by from-date. */
512	    public List<DatedValue> history(String sheetId, String key) {
513	        return jdbc.query("SELECT from_date, setting_value FROM " + AsOf.table("setting_from") + " WHERE sheet_id = ? AND setting_key = ? ORDER BY from_date",
514	                (rs, n) -> new DatedValue(rs.getDate("from_date").toLocalDate().toString(), rs.getString("setting_value")),
515	                sheetId, key);
516	    }
517	
518	    /** A dated setting's value from a from-date (yyyy-MM-dd). */
519	    public record DatedValue(String from, String value) {
520	    }
521	
522	    /** A dated setting's value in force on the sheet's today; "" when there is none. */
523	    public String current(String sheetId, String key) {
524	        return on(sheetId, key, sheets.today(sheetId));
525	    }
526	
527	    /** The clerk limit in force on the sheet's today; null when there is none. */
528	    public BigDecimal clerkLimit(String sheetId) {
529	        String value = current(sheetId, CLERK_LIMIT);
530	        return value.isEmpty() ? null : new BigDecimal(value);
531	    }
532	
533	    /** The cap in force on the sheet's today, with two decimals: what a person's due-total is at most; null when there is none. */
534	    public BigDecimal cap(String sheetId) {
535	        String value = current(sheetId, CAP);
536	        return value.isEmpty() ? null : new BigDecimal(value);
537	    }
538	
539	    /** The proof threshold in force on the date: a claim dated then whose due is above it is settled only with a proof; null when there is none. */
540	    public BigDecimal proofThreshold(String sheetId, LocalDate date) {
541	        String value = on(sheetId, PROOF_THRESHOLD, date);
542	        return value.isEmpty() ? null : new BigDecimal(value);
543	    }
544	
545	    /** The note threshold in force on the date: a claim dated then whose due is above it is opened only with a note; null when there is none. */
546	    public BigDecimal noteThreshold(String sheetId, LocalDate date) {
547	        String value = on(sheetId, NOTE_THRESHOLD, date);
548	        return value.isEmpty() ? null : new BigDecimal(value);
549	    }
550	
551	    /** A person's due-total held to the sheet's cap; null (n/a) stays null. */
552	    public BigDecimal capped(String sheetId, BigDecimal dueTotal) {
553	        BigDecimal cap = cap(sheetId);
554	        return dueTotal == null || cap == null ? dueTotal : dueTotal.min(cap);
555	    }
556	
557	    /** The floor in force on the date, with two decimals: what a claim's live due is at least; 1.00 when none is. */
558	    public BigDecimal floor(String sheetId, LocalDate date) {
559	        String value = on(sheetId, FLOOR, date);
560	        return new BigDecimal(value.isEmpty() ? FLOOR_DEFAULT : value);
561	    }
562	
563	    /** The terms in force on the date: the number of days after its date a claim is due by; 14 when none are. */
564	    public int terms(String sheetId, LocalDate date) {
565	        String value = on(sheetId, TERMS, date);
566	        return Integer.parseInt(value.isEmpty() ? TERMS_DEFAULT : value);
567	    }
568	
569	    /** The key a grade's own terms are kept under: terms-<grade>. */
570	    public static String gradeTermsKey(String grade) {
571	        return TERMS + "-" + grade;
572	    }
573	
574	    /** The terms of the grade in force on the date: its own terms, or the sheet's terms when it has none of its own. */
575	    public int terms(String sheetId, String grade, LocalDate date) {
576	        String value = on(sheetId, gradeTermsKey(grade), date);
577	        return value.isEmpty() ? terms(sheetId, date) : Integer.parseInt(value);
578	    }
579	
580	    /** The key a grade's grace days are kept under: grace-<grade>. */
581	    public static String gradeGraceKey(String grade) {
582	        return "grace-" + grade;
583	    }
584	
585	    /** The grace days of the grade in force on the date: days past a claim's due-by before it is overdue; 0 when none are (blank is none). */
586	    public int grace(String sheetId, String grade, LocalDate date) {
587	        String value = grade == null ? "" : on(sheetId, gradeGraceKey(grade), date);
588	        return value.isEmpty() ? 0 : Integer.parseInt(value);
589	    }
590	
591	    /**
592	     * The date the claim's overdue count runs from: its due-by plus the grace days, in force on its date, of the grade its person
593	     * had on its date. It is overdue once this is before the sheet's today, and its late charge's 30-day boundaries count from it.
594	     */
595	    public LocalDate overdueFrom(Claim claim) {
596	        Person person = people.find(claim.sheetId(), claim.personId());
597	        String grade = person == null ? null : person.gradeOn(claim.date());
598	        return claim.dueBy().plusDays(grace(claim.sheetId(), grade, claim.date()));
599	    }
600	
601	    /** Whether the claim is overdue on {@code today}: open (OPEN or PENDING), not deferred, and its {@link #overdueFrom} is before it. */
602	    public boolean overdue(Claim claim, LocalDate today) {
603	        return claim.status().isOpen() && !claim.deferredOn(today) && claim.dueBy() != null && today != null
604	                && overdueFrom(claim).isBefore(today);
605	    }
606	
607	    /** The late percent in force on the date, with two decimals: what an overdue claim gains per full 30 days; 0.00 when none is. */
608	    public BigDecimal latePct(String sheetId, LocalDate date) {
609	        String value = on(sheetId, LATE_PCT, date);
610	        return new BigDecimal(value.isEmpty() ? LATE_PCT_DEFAULT : value);
611	    }
612	
613	    /** The policy date: the one set, or the sheet's today when it is blank. */
614	    public LocalDate policyDate(String sheetId) {
615	        String value = get(sheetId, POLICY_DATE);
616	        return value.isEmpty() ? sheets.today(sheetId) : LocalDate.parse(value);
617	    }
618	
619	    /** The date from which opened claims are numbered within their period; null when it is off. */
620	    public LocalDate periodNumberingFrom(String sheetId) {
621	        String value = get(sheetId, PERIOD_NUMBERING_FROM);
622	        return value.isEmpty() ? null : LocalDate.parse(value);
623	    }
624	
625	    /** The date a new claim left undated is given: the entry date when one is set, else the sheet's today. */
626	    public LocalDate entryDate(String sheetId) {
627	        String value = get(sheetId, ENTRY_DATE);
628	        return value.isEmpty() ? sheets.today(sheetId) : LocalDate.parse(value);
629	    }
630	
631	    /** The grace days: how many days after its to-date an open period is closed when the sheet's today is changed; null when it is off. */
632	    public Integer graceDays(String sheetId) {
633	        String value = get(sheetId, GRACE_DAYS);
634	        return value.isEmpty() ? null : Integer.valueOf(value);
635	    }
636	
637	    /**
638	     * How the claim's live figures round: half up when it is dated before the policy date, half to even on or after it.
639	     * A correction rounds by the date of the claim it corrects.
640	     */
641	    public RoundingMode rounding(Claim claim) {
642	        LocalDate date = claim.date();
643	        if (claim.isCorrection() && claim.corrects() != null) {
644	            Claim corrected = claims.findByNumber(claim.sheetId(), claim.personId(), claim.corrects());
645	            if (corrected != null) {
646	                date = corrected.date();
647	            }
648	        }
649	        return date.isBefore(policyDate(claim.sheetId())) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
650	    }
651	
652	    /** The claim's rate figure at the rate (a percent): its amount times the rate, rounded by {@link #rounding}, not yet floored; null (no rate) stays null. */
653	    public BigDecimal live(Claim claim, BigDecimal rate) {
654	        return rate == null ? null : claim.amount().multiply(rate).movePointLeft(2).setScale(2, rounding(claim));
655	    }
656	
657	    /**
658	     * A claim's live due from its rate figure (or the figure a statement bound): the figure with its late charge added on top, then raised
659	     * to the floor in force on the claim's date ({@link #floored}). An open (OPEN or PENDING) claim whose due-by (fixed when it was made) plus
660	     * its grade's grace ({@link #overdueFrom}) is before {@code today} gains, for every full 30 days it is overdue, the late percent in force on
661	     * that boundary date (the due-by plus the grace plus 30, 60, 90 ... days)
662	     * of the figure plus the charges of the boundaries before it (compounding), each charge rounded by {@link #rounding}, the charges added up; a boundary whose percent is 0.00 adds nothing.
663	     * The charge is never bound by a statement, so it follows the sheet's today; null (no figure) stays null.
664	     * A correction has no late charge and no floor, and a deferred claim no late charge (it is not overdue until the sheet's today reaches its date).
665	     */
666	    public BigDecimal withLate(Claim claim, BigDecimal figure, LocalDate today) {
667	        return floored(claim, lateAdded(claim, figure, today));
668	    }
669	
670	    /** The figure with the claim's late charge on {@code today} added on top (see {@link #withLate}), not floored. */
671	    private BigDecimal lateAdded(Claim claim, BigDecimal figure, LocalDate today) {
672	        if (figure == null || !claim.status().isOpen() || claim.isCorrection() || claim.deferredOn(today)) {
673	            return figure;
674	        }
675	        LocalDate dueBy = overdueFrom(claim);
676	        if (!dueBy.isBefore(today)) {
677	            return figure;
678	        }
679	        long periods = ChronoUnit.DAYS.between(dueBy, today) / 30;
680	        RoundingMode rounding = rounding(claim);
681	        BigDecimal total = figure;
682	        for (long n = 1; n <= periods; n++) {
683	            BigDecimal pct = latePct(claim.sheetId(), dueBy.plusDays(30 * n));
684	            if (pct.signum() != 0) {
685	                total = total.add(total.multiply(pct).movePointLeft(2).setScale(2, rounding));
686	            }
687	        }
688	        return total;
689	    }
690	
691	    /** The claim's due (its figure plus its late charge) raised to the floor in force on the claim's date; null (no due) stays null, and a correction's due has no floor. */
692	    public BigDecimal floored(Claim claim, BigDecimal due) {
693	        return due == null || claim.isCorrection() ? due : due.max(floor(claim.sheetId(), claim.date()));
694	    }
695	
696	    /** The key an action's permitted roles are kept under: perm-<action>. */
697	    public static String permKey(String action) {
698	        return "perm-" + action;
699	    }
700	
701	    /** The roles an action is permitted to, as saved: a comma separated list, or "" for the standing rule. */
702	    public String perm(String sheetId, String action) {
703	        return get(sheetId, permKey(action));
704	    }
705	
706	    /** The standing rule: reassign and reopen by steward; open, settle, void and close by clerk and steward. */
707	    private static List<String> standing(String action) {
708	        return action.equals("reassign") || action.equals("reopen") ? List.of(STEWARD) : ROLES;
709	    }
710	
711	    /** Whether the user's role may take the action on the sheet: as the permission matrix has it, else by the standing rule. */
712	    public boolean permits(String sheetId, String action, String user) {
713	        String saved = perm(sheetId, action);
714	        List<String> roles = saved.isEmpty() ? standing(action) : List.of(saved.split(","));
715	        return roles.contains(role(sheetId, user));
716	    }
717	
718	    /** The sheet's roles, by user name. */
719	    public List<Role> roles(String sheetId) {
720	        return jdbc.query("SELECT * FROM " + AsOf.table("sheet_role") + " WHERE sheet_id = ? ORDER BY user_name",
721	                (rs, n) -> new Role(rs.getString("sheet_id"), rs.getString("user_name"), rs.getString("role")), sheetId);
