793	public class ValidateDelegation {
794	
795	    private static final DateTimeFormatter ISO = DateTimeFormatter.ofPattern("uuuu-MM-dd")
796	            .withResolverStyle(ResolverStyle.STRICT);
797	
798	    // Only a steward (by the role the sheet gives them, not one delegated to them) delegates. The user name must not be
799	    // blank; a blank from-date is the sheet's today, a blank to-date the from-date; a to-date before the from-date is refused.
800	    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody DelegateRequest body,
801	            ServerHttpConnection connection, Settings settings, Sheets sheets, Out<Delegation> delegation)
802	            throws InvalidSettingException {
803	        String id = sheetId.trim();
804	        String by = Audit.user(connection).trim();
805	        if (!Settings.STEWARD.equals(settings.givenRole(id, by))) {
806	            throw new InvalidSettingException("Only a steward can delegate the steward role.");
807	        }
808	        String user = body == null || body.user() == null ? "" : body.user().trim();
809	        if (user.isEmpty()) {
810	            throw new InvalidSettingException("A user name is needed.");
811	        }
812	        LocalDate from = parse(body.from());
813	        if (from == null) {
814	            from = sheets.today(id);
815	        }
816	        LocalDate to = parse(body.to());
817	        if (to == null) {
818	            to = from;
819	        }
820	        if (to.isBefore(from)) {
821	            throw new InvalidSettingException("The to-date is before the from-date.");
822	        }
823	        delegation.set(new Delegation(id, user, from, to, by));
824	    }
825	
826	    private static LocalDate parse(String value) throws InvalidSettingException {
827	        String raw = value == null ? "" : value.trim();
828	        if (raw.isEmpty()) {
829	            return null;
830	        }
831	        try {
832	            return LocalDate.parse(raw, ISO);
833	        } catch (DateTimeParseException e) {
834	            throw new InvalidSettingException("Not a date (yyyy-mm-dd): " + raw);
835	        }
836	    }
837	}
