877	public class ValidateSettings {
878	
879	    private static final Pattern DAYS = Pattern.compile("\\d{1,4}");
880	    private static final Pattern AMOUNT = Pattern.compile("\\d{1,9}(\\.\\d{1,2})?");
881	
882	    // The amounts are kept with two decimals. A blank floor leaves the floor as it is; a blank clerk limit is
883	    // no limit, unless a floor, terms, late percent or policy date are saved with it, when the clerk limit is left as it is (and null
884	    // leaves it as it is too). Anything else that is not an amount of 0.00 or more with up to two decimals is
885	    // refused. Blank terms are left as they are; otherwise they must be a whole number of days, 0 or more.
886	    // A blank late percent is left as it is; otherwise it must be a percent of 0.00 or more, with up to two decimals.
887	    // A missing policy date is left as it is; a blank one is none (the sheet's today is); otherwise it must be a yyyy-MM-dd date.
888	    // A grade's own terms are like the terms: blank is left as it is, otherwise a whole number of days, 0 or more,
889	    // and only a grade (A, B or C) may have them.
890	    // A grade's grace days are dated like its terms: blank is none, otherwise a whole number of days, 0 or more, and only for a grade (A, B or C).
891	    // The period numbering from-date is the same: missing is left as it is, blank is off, otherwise a yyyy-MM-dd date.
892	    // The cap is missing: left as it is, blank: none, otherwise an amount of 0.00 or more with up to two decimals.
893	    // The proof threshold is like the cap: missing is left as it is, blank is none, otherwise an amount of 0.00 or more with up to two decimals.
894	    // The note threshold is like the cap too.
895	    // The grace days are missing: left as they are, blank: off, otherwise a whole number of days, 0 or more (not dated).
896	    // The entry date is like the period numbering from-date: missing is left as it is, blank is off (the sheet's today), otherwise a yyyy-MM-dd date.
897	    // An action's permitted roles are missing: left as they are, blank: the standing rule, otherwise clerk or steward, separated by commas.
898	    // A from-date, given by setting key, is blank (the sheet's today) or a yyyy-MM-dd date, and only a dated setting has one.
899	    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody SettingsRequest body,
900	            Out<SheetSettings> settingsOut) throws InvalidSettingException {
901	        String floor = body == null || body.floor() == null ? "" : body.floor().trim();
902	        if (!floor.isEmpty() && !AMOUNT.matcher(floor).matches()) {
903	            throw new InvalidSettingException("The floor must be an amount of 0.00 or more, with up to two decimals.");
904	        }
905	        String typed = body == null || body.clerkLimit() == null ? null : body.clerkLimit().trim();
906	        if (typed != null && !typed.isEmpty() && !AMOUNT.matcher(typed).matches()) {
907	            throw new InvalidSettingException("The clerk limit must be an amount of 0.00 or more, with up to two decimals.");
908	        }
909	        String terms = body == null || body.terms() == null ? "" : body.terms().trim();
910	        if (!terms.isEmpty() && !DAYS.matcher(terms).matches()) {
911	            throw new InvalidSettingException("The terms must be a whole number of days, 0 or more.");
912	        }
913	        SortedMap<String, String> gradeTerms = new TreeMap<>();
914	        if (body != null && body.gradeTerms() != null) {
915	            for (Map.Entry<String, String> entry : body.gradeTerms().entrySet()) {
916	                String grade = entry.getKey() == null ? "" : entry.getKey().trim();
917	                String days = entry.getValue() == null ? "" : entry.getValue().trim();
918	                if (days.isEmpty()) {
919	                    continue;
920	                }
921	                if (!Settings.GRADES.contains(grade)) {
922	                    throw new InvalidSettingException("Terms can be set only for grade A, B or C.");
923	                }
924	                if (!DAYS.matcher(days).matches()) {
925	                    throw new InvalidSettingException("The terms of grade " + grade + " must be a whole number of days, 0 or more.");
926	                }
927	                gradeTerms.put(grade, Integer.toString(Integer.parseInt(days)));
928	            }
929	        }
930	        SortedMap<String, String> gradeGrace = new TreeMap<>();
931	        if (body != null && body.gradeGrace() != null) {
932	            for (Map.Entry<String, String> entry : body.gradeGrace().entrySet()) {
933	                String grade = entry.getKey() == null ? "" : entry.getKey().trim();
934	                if (entry.getValue() == null) {
935	                    continue;
936	                }
937	                String days = entry.getValue().trim();
938	                if (!Settings.GRADES.contains(grade)) {
939	                    throw new InvalidSettingException("Grace days can be set only for grade A, B or C.");
940	                }
941	                if (!days.isEmpty() && !DAYS.matcher(days).matches()) {
942	                    throw new InvalidSettingException("The grace days of grade " + grade + " must be a whole number of days, 0 or more.");
943	                }
944	                gradeGrace.put(grade, days.isEmpty() ? "" : Integer.toString(Integer.parseInt(days)));
945	            }
946	        }
947	        String latePct = body == null || body.latePct() == null ? "" : body.latePct().trim();
948	        if (!latePct.isEmpty() && !AMOUNT.matcher(latePct).matches()) {
949	            throw new InvalidSettingException("The late percent must be a percent of 0.00 or more, with up to two decimals.");
950	        }
951	        String policyDate = body == null || body.policyDate() == null ? null : body.policyDate().trim();
952	        if (policyDate != null && !policyDate.isEmpty()) {
953	            try {
954	                policyDate = LocalDate.parse(policyDate).toString();
955	            } catch (DateTimeParseException e) {
956	                throw new InvalidSettingException("The policy date must be a date (yyyy-mm-dd).");
957	            }
958	        }
959	        String numberingFrom = body == null || body.periodNumberingFrom() == null ? null : body.periodNumberingFrom().trim();
960	        if (numberingFrom != null && !numberingFrom.isEmpty()) {
961	            try {
962	                numberingFrom = LocalDate.parse(numberingFrom).toString();
963	            } catch (DateTimeParseException e) {
964	                throw new InvalidSettingException("The period numbering from-date must be a date (yyyy-mm-dd).");
965	            }
966	        }
967	        String cap = body == null || body.cap() == null ? null : body.cap().trim();
968	        if (cap != null && !cap.isEmpty()) {
969	            if (!AMOUNT.matcher(cap).matches()) {
970	                throw new InvalidSettingException("The cap must be an amount of 0.00 or more, with up to two decimals.");
971	            }
972	            cap = twoDecimals(cap);
973	        }
974	        String threshold = body == null || body.proofThreshold() == null ? null : body.proofThreshold().trim();
975	        if (threshold != null && !threshold.isEmpty()) {
976	            if (!AMOUNT.matcher(threshold).matches()) {
977	                throw new InvalidSettingException("The proof threshold must be an amount of 0.00 or more, with up to two decimals.");
978	            }
979	            threshold = twoDecimals(threshold);
980	        }
981	        String noteThreshold = body == null || body.noteThreshold() == null ? null : body.noteThreshold().trim();
982	        if (noteThreshold != null && !noteThreshold.isEmpty()) {
983	            if (!AMOUNT.matcher(noteThreshold).matches()) {
984	                throw new InvalidSettingException("The note threshold must be an amount of 0.00 or more, with up to two decimals.");
985	            }
986	            noteThreshold = twoDecimals(noteThreshold);
987	        }
988	        String grace = body == null || body.graceDays() == null ? null : body.graceDays().trim();
989	        if (grace != null && !grace.isEmpty()) {
990	            if (!DAYS.matcher(grace).matches()) {
991	                throw new InvalidSettingException("The grace days must be a whole number of days, 0 or more.");
992	            }
993	            grace = Integer.toString(Integer.parseInt(grace));
994	        }
995	        String entryDate = body == null || body.entryDate() == null ? null : body.entryDate().trim();
996	        if (entryDate != null && !entryDate.isEmpty()) {
997	            try {
998	                entryDate = LocalDate.parse(entryDate).toString();
999	            } catch (DateTimeParseException e) {
1000	                throw new InvalidSettingException("The entry date must be a date (yyyy-mm-dd).");
1001	            }
1002	        }
1003	        Map<String, LocalDate> from = new java.util.HashMap<>();
1004	        if (body != null && body.from() != null) {
1005	            for (Map.Entry<String, String> entry : body.from().entrySet()) {
1006	                String key = entry.getKey() == null ? "" : entry.getKey().trim();
1007	                String date = entry.getValue() == null ? "" : entry.getValue().trim();
1008	                if (date.isEmpty()) {
1009	                    continue;
1010	                }
1011	                if (!Settings.DATED.contains(key)) {
1012	                    throw new InvalidSettingException("Only a setting that carries a figure has a from-date.");
1013	                }
1014	                try {
1015	                    from.put(key, LocalDate.parse(date));
1016	                } catch (DateTimeParseException e) {
1017	                    throw new InvalidSettingException("The from-date must be a date (yyyy-mm-dd).");
1018	                }
1019	            }
1020	        }
1021	        Map<String, String> perms = new java.util.LinkedHashMap<>();
1022	        if (body != null && body.perms() != null) {
1023	            for (String action : body.perms().keySet()) {
1024	                if (!Settings.PERM_ACTIONS.contains(action)) {
1025	                    throw new InvalidSettingException("Permissions are set only for open, settle, void, reassign, close and reopen.");
1026	                }
1027	            }
1028	            for (String action : Settings.PERM_ACTIONS) {
1029	                String typedRoles = body.perms().get(action);
1030	                if (typedRoles == null) {
1031	                    continue;
1032	                }
1033	                java.util.List<String> roles = new java.util.ArrayList<>();
1034	                if (!typedRoles.isBlank()) {
1035	                    for (String role : typedRoles.split(",")) {
1036	                        String r = role.trim();
1037	                        if (!Settings.ROLES.contains(r)) {
1038	                            throw new InvalidSettingException("The roles allowed to " + action + " must be clerk or steward, separated by commas.");
1039	                        }
1040	                        if (!roles.contains(r)) {
1041	                            roles.add(r);
1042	                        }
1043	                    }
1044	                }
1045	                perms.put(action, String.join(",", roles));
1046	            }
1047	        }
1048	        boolean others = !floor.isEmpty() || !terms.isEmpty() || !gradeTerms.isEmpty() || !gradeGrace.isEmpty() || !latePct.isEmpty() || policyDate != null
1049	                || numberingFrom != null || cap != null || threshold != null || noteThreshold != null || grace != null || entryDate != null || !perms.isEmpty();
1050	        if (typed == null && !others) {
1051	            typed = "";
1052	        }
1053	        String limit = typed == null || (typed.isEmpty() && others) ? null
1054	                : typed.isEmpty() ? "" : twoDecimals(typed);
1055	        settingsOut.set(new SheetSettings(sheetId.trim(), limit, floor.isEmpty() ? null : twoDecimals(floor),
1056	                terms.isEmpty() ? null : Integer.toString(Integer.parseInt(terms)),
1057	                latePct.isEmpty() ? null : twoDecimals(latePct), policyDate, numberingFrom, cap, threshold, grace, noteThreshold, entryDate, gradeTerms, gradeGrace, from, perms));
1058	    }
1059	
1060	    private static String twoDecimals(String amount) {
1061	        return new BigDecimal(amount).setScale(2, RoundingMode.UNNECESSARY).toPlainString();
1062	    }
